float shaderlod_maximum_horizon_angle_reuse(
    vec3 view_slice_dir,
    vec3 viewer_dir,
    vec3 screen_pos,
    vec3 view_pos,
    float radius,
    float dither,
    bool is_lod
) {
    float step_size = (GTAO_RADIUS * rcp(float(GTAO_HORIZON_STEPS))) * radius;

    float max_cos_theta = -1.0;

    vec2 ray_step =
        (view_to_screen_space(
             view_pos + view_slice_dir * step_size,
             true,
             is_lod
         ) -
         screen_pos)
            .xy;
    vec2 ray_pos = screen_pos.xy +
        ray_step * (dither + max_of(view_pixel_size) * rcp_length(ray_step));

    // Reuse only consecutive in-range depth texels; keep every fractional ray point.
    ivec2 depth_texture_size = textureSize(combined_depth_tex, 0);
    bool depth_cache_valid = false;
    ivec2 depth_cache_texel = ivec2(0);
    float depth_cache_value = 0.0;

    for (int i = 0; i < GTAO_HORIZON_STEPS; ++i, ray_pos += ray_step) {
        ivec2 texel =
            ivec2(clamp01(ray_pos) * view_res * taau_render_scale - 0.5);
        bool cacheable_texel = all(greaterThanEqual(texel, ivec2(0))) &&
            all(lessThan(texel, depth_texture_size));
        float depth;
        if (cacheable_texel && depth_cache_valid &&
            all(equal(texel, depth_cache_texel))) {
            depth = depth_cache_value;
        } else {
            depth = texelFetch(combined_depth_tex, texel, 0).x;
        }
        // Out-of-range upstream fetches are undefined: never reuse their result.
        depth_cache_valid = cacheable_texel;
        depth_cache_texel = texel;
        depth_cache_value = depth;

        if (depth == 1.0 || depth < hand_depth || depth == screen_pos.z) {
            continue;
        }

        vec3 offset = screen_to_view_space(
                          combined_projection_matrix_inverse,
                          vec3(ray_pos, depth),
                          true
                      ) -
            view_pos;

        float len_sq = length_squared(offset);
        float norm = inversesqrt(len_sq);

        float distance_falloff = linear_step(
            GTAO_FALLOFF_START * GTAO_RADIUS,
            GTAO_RADIUS,
            len_sq * norm * rcp(radius)
        );

        float cos_theta = dot(viewer_dir, offset) * norm;
        cos_theta = mix(cos_theta, -1.0, distance_falloff);

        max_cos_theta = max(cos_theta, max_cos_theta);
